const webhookBody = $('Webhook').item.json.body;
const current = $input.item.json;

if (current.error) {
  return [{
    json: {
      callback_url: webhookBody.callback_url,
      api_key: webhookBody.api_key,
      success: false,
      error: String(current.error.message || current.error),
    },
  }];
}

let parsed;
try {
  const text = current.content[0].text;
  parsed = JSON.parse(text);
} catch (e) {
  return [{
    json: {
      callback_url: webhookBody.callback_url,
      api_key: webhookBody.api_key,
      success: false,
      error: `Could not parse AI response as JSON: ${e.message}`,
    },
  }];
}

return [{
  json: {
    callback_url: webhookBody.callback_url,
    api_key: webhookBody.api_key,
    success: true,
    message: parsed.message,
    hashtags: parsed.hashtags || [],
  },
}];
